import { createPlayerError } from "../core/errors.js";
import { UniversalPlayer } from "../core/player.js";
import type { PlayerOptions, PlayerSourceInput } from "../core/types.js";

/** Options accepted by {@link mountUniversalPlayer}. */
export interface MountOptions extends Omit<PlayerOptions, "container"> {
  readonly source?: PlayerSourceInput;
}

/**
 * Creates a player inside an element (or the first element matching a selector).
 */
export function mountUniversalPlayer(
  target: string | HTMLElement,
  options: MountOptions = {},
): UniversalPlayer {
  const container =
    typeof target === "string" ? document.querySelector<HTMLElement>(target) : target;

  if (container === null) {
    const selector = typeof target === "string" ? target : "<element>";

    throw createPlayerError(`No element matches "${selector}".`, {
      code: "invalid-argument",
      details: { selector },
    });
  }

  const { source, ...rest } = options;

  return new UniversalPlayer({
    container,
    ...(source === undefined ? {} : { source }),
    ...rest,
  });
}
